using System.IO;`nusing System.Diagnostics;`nusing PhotoReview.Core.Model;`nusing PhotoReview.Imaging.LibRaw;`nusing System.Windows.Media;`nusing System.Windows.Media.Imaging;`n`nnamespace PhotoReview.Imaging.Tests.Raw;`n`n[Trait("Category", "Native")]`npublic sealed class LibRawDecoderTests`n{`n    private static readonly string CorpusDirectory = Path.GetFullPath(`n        Path.Combine(AppContext.BaseDirectory, "../../../../../tests/Fixtures/raw-corpus"));`n`n    [Fact]`n    [Trait("Category", "Native")]`n    public void AvailabilityProbe_LoadsAndInitializesPinnedRuntime()`n    {`n        Assert.True(LibRawAvailability.Probe(out var reason), reason);`n        Assert.Null(reason);`n        Assert.True(LibRawAvailability.Probe(out reason));`n        Assert.Null(reason);`n    }`n`n    [Fact]`n    public void Decode_OfficialCorpusSamples_ReturnsValidRgbBackedBitmap()`n    {`n        if (!Directory.Exists(CorpusDirectory)) return;`n        var files = Directory.GetFiles(CorpusDirectory)`n            .Where(path => PhotoReview.Core.Catalog.ImageFileTypes.RawExtensions.Contains(Path.GetExtension(path)))`n            .OrderBy(path => path, StringComparer.OrdinalIgnoreCase)`n            .ToArray();`n        if (files.Length == 0) return;`n`n        var decoder = new LibRawDecoder();`n        using var process = Process.GetCurrentProcess();`n        var peakPrivateBytes = process.PrivateMemorySize64;`n        var measurements = new List<string>();`n        foreach (var path in files)`n        {`n            var stopwatch = Stopwatch.StartNew();`n            var request = new DecodeRequest(path, DecodeBox.Unbounded);`n            var image = decoder.Decode(request);`n            stopwatch.Stop();`n            var info = decoder.ReadInfo(path);`n`n            Assert.True(image.PixelWidth > 0);`n            Assert.True(image.PixelHeight > 0);`n            Assert.Equal(DecoderBackend.LibRaw, image.ActualBackend);`n            var bitmap = Assert.IsAssignableFrom<BitmapSource>(image.PlatformImage);`n            Assert.Equal(PixelFormats.Bgr32, bitmap.Format);`n            Assert.Equal(96, bitmap.DpiX);`n            Assert.Equal(96, bitmap.DpiY);`n            Assert.Equal(image.PixelWidth, info.PixelWidth);`n            Assert.Equal(image.PixelHeight, info.PixelHeight);`n`n            measurements.Add($"{Path.GetFileName(path)} {image.PixelWidth}x{image.PixelHeight} {stopwatch.Elapsed.TotalMilliseconds:F0} ms");`n            peakPrivateBytes = Math.Max(peakPrivateBytes, process.PrivateMemorySize64);`n`n            if (Path.GetFileName(path).Equals("Canon - EOS 350D - RAW (3_2).CR2", StringComparison.OrdinalIgnoreCase))`n            {`n                var bounded = decoder.Decode(new DecodeRequest(path, new DecodeBox(640, 480)));`n                Assert.True(bounded.Downscaled);`n                Assert.True(bounded.PixelWidth <= 640);`n                Assert.True(bounded.PixelHeight <= 480);`n                Assert.Equal(image.OriginalWidth, bounded.OriginalWidth);`n                Assert.Equal(image.OriginalHeight, bounded.OriginalHeight);`n            }`n        }`n`n        Console.WriteLine($"LibRaw corpus: {files.Length}/{files.Length} decoded; peak private bytes={peakPrivateBytes}; "`n            + string.Join(" | ", measurements));`n    }`n`n    [Fact]`n    public void Decode_RejectsRequestThatWouldLeaveOrientationUnapplied()`n    {`n        var error = Assert.Throws<NotSupportedException>(() =>`n            new LibRawDecoder().Decode(new DecodeRequest("unused.cr2", DecodeBox.Unbounded, applyOrientation: false)));`n`n        Assert.Contains("always applies", error.Message, StringComparison.Ordinal);`n    }`n}`n